// ==================================================
// Authorized Response Test Input
//
// TEMPORARY PARTIAL EXECUTION TEST.
//
// Simulates one authorized identity response action
// that the mock connector will complete partially.
//
// Expected:
// - connector status = partial
// - changed = true
// - bundle status reflects partial execution
//
// No real response action is executed.
// ==================================================

return [
  {
    json: {

      response_execution_authorization_version:
        "1.0",

      alert_id:
        "ALERT-0001",

      status:
        "authorized_for_execution",

      execution_authorized:
        true,

      approval_request_id:
        "approval-ALERT-0001-test",

      authorized_action_count:
        1,

      authorized_actions: [
        {

          execution_id:
            "ALERT-0001-action-hardfail-1",

          action_id:
            "action-1",

          action:
            "revoke_sessions",

          target: {

            type:
              "user",

            value:
              "hardfail.user@example.com"
          },

          priority:
            "high",

          reason:
            "Controlled partial execution test.",

          evidence_sources: [
            "get_signins"
          ],

          authorization: {

            approval_request_id:
              "approval-ALERT-0001-test",

            approved_by:
              "manual-test-approver",

            approved_at:
              "2026-08-24T23:27:08.323Z"
          }
        }
      ]
    }
  }
];

// ==================================================
// Response Action Expander
//
// Expands an execution authorization envelope into
// one execution request per authorized action.
//
// Security properties:
// - execution authorization must be explicit
// - only authorized actions are expanded
// - authorization metadata is preserved
// - no connector execution occurs here
// ==================================================

const input = $json;


// --------------------------------------------------
// 1. Validate authorization envelope
// --------------------------------------------------

if (
  !input ||
  typeof input !== "object" ||
  Array.isArray(input)
) {
  throw new Error(
    "Response Action Expander requires an execution authorization envelope"
  );
}


if (
  input.response_execution_authorization_version !== "1.0"
) {
  throw new Error(
    "Response Action Expander requires response_execution_authorization_version '1.0'"
  );
}


if (
  input.status !== "authorized_for_execution"
) {
  throw new Error(
    "Response Action Expander requires status 'authorized_for_execution'"
  );
}


if (
  input.execution_authorized !== true
) {
  throw new Error(
    "Response Action Expander requires execution_authorized=true"
  );
}


if (
  typeof input.alert_id !== "string" ||
  input.alert_id.trim() === ""
) {
  throw new Error(
    "Response Action Expander requires alert_id"
  );
}


if (
  typeof input.approval_request_id !== "string" ||
  input.approval_request_id.trim() === ""
) {
  throw new Error(
    "Response Action Expander requires approval_request_id"
  );
}


if (
  !Array.isArray(input.authorized_actions) ||
  input.authorized_actions.length === 0
) {
  throw new Error(
    "Response Action Expander requires at least one authorized action"
  );
}


if (
  input.authorized_action_count !==
  input.authorized_actions.length
) {
  throw new Error(
    "authorized_action_count does not match authorized_actions length"
  );
}


// --------------------------------------------------
// 2. Supported execution actions
// --------------------------------------------------

const supportedActions =
  new Map([
    [
      "revoke_sessions",
      "user"
    ],

    [
      "disable_user",
      "user"
    ],

    [
      "isolate_endpoint",
      "host"
    ],

    [
      "block_ip",
      "ip"
    ],

    [
      "block_domain",
      "domain"
    ],

    [
      "delete_email",
      "email"
    ]
  ]);


// --------------------------------------------------
// 3. Expand actions
// --------------------------------------------------

const output = [];


input.authorized_actions.forEach(
  (action, index) => {

    if (
      !action ||
      typeof action !== "object" ||
      Array.isArray(action)
    ) {
      throw new Error(
        `authorized_actions[${index}] must be an object`
      );
    }


    if (
      typeof action.execution_id !== "string" ||
      action.execution_id.trim() === ""
    ) {
      throw new Error(
        `authorized_actions[${index}].execution_id is required`
      );
    }


    if (
      typeof action.action_id !== "string" ||
      action.action_id.trim() === ""
    ) {
      throw new Error(
        `authorized_actions[${index}].action_id is required`
      );
    }


    if (
      typeof action.action !== "string" ||
      !supportedActions.has(action.action)
    ) {
      throw new Error(
        `authorized_actions[${index}].action is unsupported`
      );
    }


    if (
      !action.target ||
      typeof action.target !== "object" ||
      Array.isArray(action.target)
    ) {
      throw new Error(
        `authorized_actions[${index}].target is required`
      );
    }


    const expectedTargetType =
      supportedActions.get(
        action.action
      );


    if (
      action.target.type !==
      expectedTargetType
    ) {
      throw new Error(
        `authorized_actions[${index}].target.type must be '${expectedTargetType}' for action '${action.action}'`
      );
    }


    if (
      typeof action.target.value !== "string" ||
      action.target.value.trim() === ""
    ) {
      throw new Error(
        `authorized_actions[${index}].target.value is required`
      );
    }


    if (
      !action.authorization ||
      typeof action.authorization !== "object" ||
      Array.isArray(action.authorization)
    ) {
      throw new Error(
        `authorized_actions[${index}].authorization is required`
      );
    }


    if (
      action.authorization.approval_request_id !==
      input.approval_request_id
    ) {
      throw new Error(
        `authorized_actions[${index}] approval_request_id mismatch`
      );
    }


    output.push({
      json: {

        response_execution_request_version:
          "1.0",

        alert_id:
          input.alert_id,

        execution_id:
          action.execution_id,

        action_id:
          action.action_id,

        action:
          action.action,

        target:
          {
            type:
              action.target.type,

            value:
              action.target.value
          },

        priority:
          action.priority || "medium",

        reason:
          action.reason || "",

        evidence_sources:
          Array.isArray(action.evidence_sources)
            ? action.evidence_sources
            : [],

        authorization:
          {
            approval_request_id:
              input.approval_request_id,

            approved_by:
              action.authorization.approved_by,

            approved_at:
              action.authorization.approved_at
          },

        execution_context:
          {
            mode:
              "mock",

            environment:
              "local",

            idempotency_key:
              action.execution_id
          }
      }
    });
  }
);


// --------------------------------------------------
// 4. Return one item per action
// --------------------------------------------------

return output;

// ==================================================
// Mock Identity Response Connector
//
// Simulates identity response actions.
//
// Supported actions:
// - revoke_sessions
// - disable_user
//
// Test behavior:
// - normal users:
//     success
//
// - fail.user@example.com:
//     attempt 1 -> failed / retryable
//     attempt 2 -> success
//
// - hardfail.user@example.com:
//     always failed / non-retryable
//
// - partial.user@example.com:
//     partial / non-retryable
//
// IMPORTANT:
// - This is a mock connector.
// - No real Azure, Entra ID or Floci action occurs.
// ==================================================

const request = $json;


// --------------------------------------------------
// 1. Validate connector request
// --------------------------------------------------

if (
  !request ||
  typeof request !== "object" ||
  Array.isArray(request)
) {
  throw new Error(
    "Mock Identity Response Connector requires a connector request"
  );
}


if (
  request.response_connector_request_version !== "1.0"
) {
  throw new Error(
    "Mock Identity Response Connector requires response_connector_request_version '1.0'"
  );
}


if (
  request.connector !== "mock_identity_response"
) {
  throw new Error(
    "Mock Identity Response Connector received an unsupported connector"
  );
}


if (
  typeof request.alert_id !== "string" ||
  request.alert_id.trim() === ""
) {
  throw new Error(
    "Mock Identity Response Connector requires alert_id"
  );
}


if (
  typeof request.execution_id !== "string" ||
  request.execution_id.trim() === ""
) {
  throw new Error(
    "Mock Identity Response Connector requires execution_id"
  );
}


if (
  typeof request.action_id !== "string" ||
  request.action_id.trim() === ""
) {
  throw new Error(
    "Mock Identity Response Connector requires action_id"
  );
}


// --------------------------------------------------
// 2. Supported actions
// --------------------------------------------------

const supportedActions =
  new Set([
    "revoke_sessions",
    "disable_user"
  ]);


if (
  typeof request.action !== "string" ||
  !supportedActions.has(request.action)
) {
  throw new Error(
    `Mock Identity Response Connector does not support action '${request.action}'`
  );
}


// --------------------------------------------------
// 3. Validate target
// --------------------------------------------------

if (
  !request.target ||
  typeof request.target !== "object" ||
  Array.isArray(request.target)
) {
  throw new Error(
    "Mock Identity Response Connector requires target"
  );
}


if (
  request.target.type !== "user"
) {
  throw new Error(
    "Mock Identity Response Connector requires target.type='user'"
  );
}


if (
  typeof request.target.value !== "string" ||
  request.target.value.trim() === ""
) {
  throw new Error(
    "Mock Identity Response Connector requires target.value"
  );
}


// --------------------------------------------------
// 4. Validate execution context
// --------------------------------------------------

if (
  !request.execution_context ||
  typeof request.execution_context !== "object" ||
  Array.isArray(request.execution_context)
) {
  throw new Error(
    "Mock Identity Response Connector requires execution_context"
  );
}


if (
  request.execution_context.mode !== "mock"
) {
  throw new Error(
    "Mock Identity Response Connector only supports mode='mock'"
  );
}


if (
  typeof request.execution_context.idempotency_key !== "string" ||
  request.execution_context.idempotency_key.trim() === ""
) {
  throw new Error(
    "Mock Identity Response Connector requires idempotency_key"
  );
}


if (
  request.execution_context.idempotency_key !==
  request.execution_id
) {
  throw new Error(
    "idempotency_key must match execution_id"
  );
}


// --------------------------------------------------
// 5. Retry context
// --------------------------------------------------

const attempt =
  request.execution_context.attempt ?? 1;


const maxAttempts =
  request.execution_context.max_attempts ?? 2;


if (
  !Number.isInteger(attempt) ||
  attempt < 1
) {
  throw new Error(
    "execution_context.attempt must be an integer >= 1"
  );
}


if (
  !Number.isInteger(maxAttempts) ||
  maxAttempts < 1
) {
  throw new Error(
    "execution_context.max_attempts must be an integer >= 1"
  );
}


if (
  attempt > maxAttempts
) {
  throw new Error(
    "execution_context.attempt cannot exceed max_attempts"
  );
}


// --------------------------------------------------
// 6. Simulated connector behavior
// --------------------------------------------------

const targetUser =
  request.target.value;


let status =
  "success";

let changed =
  true;

let message =
  "";

let retryable =
  false;

let errorType =
  null;


// --------------------------------------------------
// Transient failure.
//
// First attempt fails.
// Retry succeeds.
// --------------------------------------------------

if (
  targetUser === "fail.user@example.com" &&
  attempt === 1
) {

  status =
    "failed";

  changed =
    false;

  retryable =
    true;

  errorType =
    "transient_connector_error";

  message =
    `Mock transient identity response failure for user '${targetUser}' on attempt ${attempt}.`;
}


else if (
  targetUser === "fail.user@example.com" &&
  attempt > 1
) {

  status =
    "success";

  changed =
    true;

  retryable =
    false;

  errorType =
    null;

  message =
    `Mock identity response succeeded for user '${targetUser}' on retry attempt ${attempt}.`;
}


// --------------------------------------------------
// Permanent failure
// --------------------------------------------------

else if (
  targetUser === "hardfail.user@example.com"
) {

  status =
    "failed";

  changed =
    false;

  retryable =
    false;

  errorType =
    "permanent_connector_error";

  message =
    `Mock permanent identity response failure for user '${targetUser}'.`;
}


// --------------------------------------------------
// Partial result
// --------------------------------------------------

else if (
  targetUser === "partial.user@example.com"
) {

  status =
    "partial";

  changed =
    true;

  retryable =
    false;

  errorType =
    null;

  message =
    `Mock identity response partially completed for user '${targetUser}'.`;
}


// --------------------------------------------------
// Normal success
// --------------------------------------------------

else if (
  request.action === "revoke_sessions"
) {

  message =
    `Mock session revocation completed for user '${targetUser}'.`;
}


else if (
  request.action === "disable_user"
) {

  message =
    `Mock user disable completed for '${targetUser}'.`;
}


// --------------------------------------------------
// 7. Build connector result
// --------------------------------------------------

const now =
  new Date().toISOString();


return [
  {
    json: {

      response_connector_result_version:
        "1.0",

      alert_id:
        request.alert_id,

      execution_id:
        request.execution_id,

      action_id:
        request.action_id,

      action:
        request.action,

      connector:
        "mock_identity_response",

      target: {
        type:
          request.target.type,

        value:
          request.target.value
      },

      status,

      outcome: {
        changed,
        message
      },

      retry: {
        retryable,
        error_type:
          errorType
      },

      execution_metadata: {

        mode:
          "mock",

        environment:
          request.execution_context.environment || "local",

        idempotency_key:
          request.execution_context.idempotency_key,

        attempt,

        max_attempts:
          maxAttempts,

        started_at:
          now,

        completed_at:
          now
      },

      authorization:
        request.authorization
    }
  }
];

// ==================================================
// Response Execution Router
//
// Routes authorized response execution requests
// to their corresponding mock response connector.
//
// Phase 10:
// - processes all execution requests deterministically
// - preserves one output item per input item
// - only mock execution is permitted
// ==================================================

const items =
  $input.all();


if (
  !Array.isArray(items) ||
  items.length === 0
) {
  throw new Error(
    "Response Execution Router requires at least one execution request"
  );
}


// --------------------------------------------------
// Supported response capabilities
// --------------------------------------------------

const capabilities = {

  revoke_sessions: {
    connector:
      "mock_identity_response",

    target_type:
      "user"
  },

  disable_user: {
    connector:
      "mock_identity_response",

    target_type:
      "user"
  },

  isolate_endpoint: {
    connector:
      "mock_endpoint_response",

    target_type:
      "host"
  },

  block_ip: {
    connector:
      "mock_network_response",

    target_type:
      "ip"
  },

  block_domain: {
    connector:
      "mock_network_response",

    target_type:
      "domain"
  },

  delete_email: {
    connector:
      "mock_mail_response",

    target_type:
      "email"
  }
};


// --------------------------------------------------
// Process every execution request
// --------------------------------------------------

const output = [];


for (
  let index = 0;
  index < items.length;
  index++
) {

  const request =
    items[index]?.json;


  // ----------------------------------------------
  // Validate request envelope
  // ----------------------------------------------

  if (
    !request ||
    typeof request !== "object" ||
    Array.isArray(request)
  ) {
    throw new Error(
      `Input item ${index} must contain an execution request`
    );
  }


  if (
    request.response_execution_request_version !== "1.0"
  ) {
    throw new Error(
      `Input item ${index} requires response_execution_request_version '1.0'`
    );
  }


  if (
    typeof request.alert_id !== "string" ||
    request.alert_id.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires alert_id`
    );
  }


  if (
    typeof request.execution_id !== "string" ||
    request.execution_id.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires execution_id`
    );
  }


  if (
    typeof request.action_id !== "string" ||
    request.action_id.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires action_id`
    );
  }


  if (
    typeof request.action !== "string" ||
    request.action.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires action`
    );
  }


  if (
    !request.target ||
    typeof request.target !== "object" ||
    Array.isArray(request.target)
  ) {
    throw new Error(
      `Input item ${index} requires target`
    );
  }


  if (
    typeof request.target.type !== "string" ||
    request.target.type.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires target.type`
    );
  }


  if (
    typeof request.target.value !== "string" ||
    request.target.value.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires target.value`
    );
  }


  // ----------------------------------------------
  // Validate authorization
  // ----------------------------------------------

  if (
    !request.authorization ||
    typeof request.authorization !== "object" ||
    Array.isArray(request.authorization)
  ) {
    throw new Error(
      `Input item ${index} requires authorization`
    );
  }


  if (
    typeof request.authorization.approval_request_id !== "string" ||
    request.authorization.approval_request_id.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires authorization.approval_request_id`
    );
  }


  if (
    typeof request.authorization.approved_by !== "string" ||
    request.authorization.approved_by.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires authorization.approved_by`
    );
  }


  if (
    typeof request.authorization.approved_at !== "string" ||
    Number.isNaN(
      Date.parse(
        request.authorization.approved_at
      )
    )
  ) {
    throw new Error(
      `Input item ${index} requires a valid authorization.approved_at`
    );
  }


  // ----------------------------------------------
  // Validate execution context
  // ----------------------------------------------

  if (
    !request.execution_context ||
    typeof request.execution_context !== "object" ||
    Array.isArray(request.execution_context)
  ) {
    throw new Error(
      `Input item ${index} requires execution_context`
    );
  }


  if (
    request.execution_context.mode !== "mock"
  ) {
    throw new Error(
      `Input item ${index}: Phase 10 only permits execution_context.mode='mock'`
    );
  }


  if (
    typeof request.execution_context.idempotency_key !== "string" ||
    request.execution_context.idempotency_key.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires execution_context.idempotency_key`
    );
  }


  if (
    request.execution_context.idempotency_key !==
    request.execution_id
  ) {
    throw new Error(
      `Input item ${index}: idempotency_key must exactly match execution_id`
    );
  }


  // ----------------------------------------------
  // Resolve capability
  // ----------------------------------------------

  const capability =
    capabilities[
      request.action
    ];


  if (!capability) {
    throw new Error(
      `Input item ${index}: unsupported response action '${request.action}'`
    );
  }


  if (
    request.target.type !==
    capability.target_type
  ) {
    throw new Error(
      `Input item ${index}: action '${request.action}' requires target type '${capability.target_type}'`
    );
  }


  // ----------------------------------------------
  // Build connector request
  // ----------------------------------------------

  output.push({
    json: {

      response_connector_request_version:
        "1.0",

      alert_id:
        request.alert_id,

      execution_id:
        request.execution_id,

      action_id:
        request.action_id,

      action:
        request.action,

      connector:
        capability.connector,

      target: {
        type:
          request.target.type,

        value:
          request.target.value
      },

      priority:
        request.priority || "medium",

      reason:
        request.reason || "",

      evidence_sources:
        Array.isArray(
          request.evidence_sources
        )
          ? request.evidence_sources
          : [],

      authorization:
        request.authorization,

      execution_context: {

        mode:
          "mock",

        environment:
          request.execution_context.environment || "local",

        idempotency_key:
          request.execution_context.idempotency_key
      }
    }
  });
}


// --------------------------------------------------
// Return one connector request per execution request
// --------------------------------------------------

return output;

// ==================================================
// Response Idempotency Guard
//
// Prevents the same execution_id from being logically
// executed more than once.
//
// Phase 10 strategy:
//
// 1. In-run idempotency:
//    A local Set guarantees duplicate detection among
//    items processed during the SAME workflow run.
//
// 2. Best-effort workflow static state:
//    Used only as a mock/provisional cross-run store.
//    It is NOT considered a durable security control.
//
// Before real Floci/Azure response execution, this
// must be replaced by persistent durable storage.
// ==================================================


// --------------------------------------------------
// 1. Read all connector requests
// --------------------------------------------------

const items =
  $input.all();


if (
  !Array.isArray(items) ||
  items.length === 0
) {
  throw new Error(
    "Response Idempotency Guard requires at least one input item"
  );
}


// --------------------------------------------------
// 2. Local per-run idempotency store
// --------------------------------------------------
//
// This guarantees deterministic duplicate detection
// inside the current workflow execution.
// --------------------------------------------------

const seenThisRun =
  new Map();


// --------------------------------------------------
// 3. Best-effort workflow static state
// --------------------------------------------------

const staticData =
  $getWorkflowStaticData("global");


if (
  !staticData.response_execution_idempotency ||
  typeof staticData.response_execution_idempotency !== "object" ||
  Array.isArray(staticData.response_execution_idempotency)
) {
  staticData.response_execution_idempotency = {};
}


const persistentMockStore =
  staticData.response_execution_idempotency;


// --------------------------------------------------
// 4. Process each execution request
// --------------------------------------------------

const output = [];


for (
  let index = 0;
  index < items.length;
  index++
) {

  const request =
    items[index]?.json;


  // ----------------------------------------------
  // Validate connector request
  // ----------------------------------------------

  if (
    !request ||
    typeof request !== "object" ||
    Array.isArray(request)
  ) {
    throw new Error(
      `Input item ${index} must contain a connector request`
    );
  }


  if (
    request.response_connector_request_version !== "1.0"
  ) {
    throw new Error(
      `Input item ${index} requires response_connector_request_version '1.0'`
    );
  }


  if (
    typeof request.alert_id !== "string" ||
    request.alert_id.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires alert_id`
    );
  }


  if (
    typeof request.execution_id !== "string" ||
    request.execution_id.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires execution_id`
    );
  }


  if (
    typeof request.action_id !== "string" ||
    request.action_id.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires action_id`
    );
  }


  if (
    typeof request.action !== "string" ||
    request.action.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires action`
    );
  }


  if (
    !request.execution_context ||
    typeof request.execution_context !== "object" ||
    Array.isArray(request.execution_context)
  ) {
    throw new Error(
      `Input item ${index} requires execution_context`
    );
  }


  const idempotencyKey =
    request.execution_context.idempotency_key;


  if (
    typeof idempotencyKey !== "string" ||
    idempotencyKey.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires execution_context.idempotency_key`
    );
  }


  if (
    idempotencyKey !==
    request.execution_id
  ) {
    throw new Error(
      `Input item ${index}: idempotency_key must exactly match execution_id`
    );
  }


  // ----------------------------------------------
  // Check duplicate inside current workflow run
  // ----------------------------------------------

  if (
    seenThisRun.has(idempotencyKey)
  ) {

    const original =
      seenThisRun.get(
        idempotencyKey
      );


    output.push({
      json: {

        ...request,

        idempotency: {

          status:
            "duplicate",

          should_execute:
            false,

          source:
            "current_workflow_run",

          idempotency_key:
            idempotencyKey,

          first_seen_at:
            original.first_seen_at,

          duplicate_detected_at:
            new Date().toISOString()
        }
      }
    });


    continue;
  }


  // ----------------------------------------------
  // Check provisional static store
  // ----------------------------------------------

  const existing =
    persistentMockStore[
      idempotencyKey
    ];


  if (existing) {

    output.push({
      json: {

        ...request,

        idempotency: {

          status:
            "duplicate",

          should_execute:
            false,

          source:
            "workflow_static_data",

          idempotency_key:
            idempotencyKey,

          first_seen_at:
            existing.first_seen_at || null,

          duplicate_detected_at:
            new Date().toISOString()
        }
      }
    });


    // Also mark it as seen locally so any further
    // copies in this run remain duplicates.

    seenThisRun.set(
      idempotencyKey,
      {
        first_seen_at:
          existing.first_seen_at ||
          new Date().toISOString()
      }
    );


    continue;
  }


  // ----------------------------------------------
  // First occurrence
  // ----------------------------------------------

  const now =
    new Date().toISOString();


  seenThisRun.set(
    idempotencyKey,
    {
      first_seen_at:
        now
    }
  );


  persistentMockStore[
    idempotencyKey
  ] = {

    execution_id:
      request.execution_id,

    alert_id:
      request.alert_id,

    action_id:
      request.action_id,

    action:
      request.action,

    target:
      request.target,

    state:
      "reserved",

    first_seen_at:
      now
  };


  output.push({
    json: {

      ...request,

      idempotency: {

        status:
          "new",

        should_execute:
          true,

        source:
          "current_workflow_run",

        idempotency_key:
          idempotencyKey,

        reserved_at:
          now
      }
    }
  });
}


// --------------------------------------------------
// 5. Return all requests
// --------------------------------------------------

return output;

// ==================================================
// Duplicate Execution Result
//
// Produces a canonical connector-style result when
// the idempotency guard detects an already reserved
// or executed execution_id.
//
// No response connector is invoked.
// ==================================================

const request = $json;


// --------------------------------------------------
// 1. Validate duplicate state
// --------------------------------------------------

if (
  !request ||
  typeof request !== "object" ||
  Array.isArray(request)
) {
  throw new Error(
    "Duplicate Execution Result requires an execution request"
  );
}


if (
  !request.idempotency ||
  typeof request.idempotency !== "object" ||
  Array.isArray(request.idempotency)
) {
  throw new Error(
    "Duplicate Execution Result requires idempotency metadata"
  );
}


if (
  request.idempotency.status !== "duplicate"
) {
  throw new Error(
    "Duplicate Execution Result requires idempotency.status='duplicate'"
  );
}


if (
  request.idempotency.should_execute !== false
) {
  throw new Error(
    "Duplicate Execution Result requires should_execute=false"
  );
}


// --------------------------------------------------
// 2. Timestamp
// --------------------------------------------------

const now =
  new Date().toISOString();


// --------------------------------------------------
// 3. Return connector-compatible duplicate result
// --------------------------------------------------

return [
  {
    json: {

      response_connector_result_version:
        "1.0",

      alert_id:
        request.alert_id,

      execution_id:
        request.execution_id,

      action_id:
        request.action_id,

      action:
        request.action,

      connector:
        request.connector,

      target:
        request.target,

      status:
        "duplicate",

      outcome: {

        changed:
          false,

        message:
          `Execution '${request.execution_id}' was not repeated because its idempotency key was already registered.`
      },

      execution_metadata: {

        mode:
          request.execution_context.mode,

        environment:
          request.execution_context.environment,

        idempotency_key:
          request.execution_context.idempotency_key,

        started_at:
          now,

        completed_at:
          now,

        first_seen_at:
          request.idempotency.first_seen_at || null
      },

      authorization:
        request.authorization
    }
  }
];

// ==================================================
// Response Execution Aggregator
//
// Aggregates canonical response execution results
// into one execution summary.
//
// Handles:
// - success
// - partial
// - failed
// - duplicate
//
// No response action is executed here.
// ==================================================

const items =
  $input.all();


if (
  !Array.isArray(items) ||
  items.length === 0
) {
  throw new Error(
    "Response Execution Aggregator requires at least one execution result"
  );
}


// --------------------------------------------------
// 1. Normalize inputs
// --------------------------------------------------

const results = [];


for (
  let index = 0;
  index < items.length;
  index++
) {

  const result =
    items[index]?.json;


  if (
    !result ||
    typeof result !== "object" ||
    Array.isArray(result)
  ) {
    throw new Error(
      `Input item ${index} must contain an execution result`
    );
  }


  if (
    result.response_execution_result_version !== "1.0"
  ) {
    throw new Error(
      `Input item ${index} requires response_execution_result_version '1.0'`
    );
  }


  if (
    typeof result.alert_id !== "string" ||
    result.alert_id.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires alert_id`
    );
  }


  if (
    typeof result.execution_id !== "string" ||
    result.execution_id.trim() === ""
  ) {
    throw new Error(
      `Input item ${index} requires execution_id`
    );
  }


  results.push(result);
}


// --------------------------------------------------
// 2. Validate shared alert context
// --------------------------------------------------

const alertIds =
  new Set(
    results.map(
      result =>
        result.alert_id
    )
  );


if (
  alertIds.size !== 1
) {
  throw new Error(
    "Response Execution Aggregator received results from multiple alert_ids"
  );
}


const alertId =
  results[0].alert_id;


// --------------------------------------------------
// 3. Aggregate counters
// --------------------------------------------------

const summary = {

  requested:
    results.length,

  success:
    0,

  partial:
    0,

  failed:
    0,

  duplicate:
    0,

  changed:
    0,

  unchanged:
    0
};


for (
  const result
  of results
) {

  if (
    result.status === "success"
  ) {
    summary.success++;
  }


  if (
    result.status === "partial"
  ) {
    summary.partial++;
  }


  if (
    result.status === "failed"
  ) {
    summary.failed++;
  }


  if (
    result.status === "duplicate"
  ) {
    summary.duplicate++;
  }


  if (
    result.changed === true
  ) {
    summary.changed++;
  } else {
    summary.unchanged++;
  }
}


// --------------------------------------------------
// 4. Derive global execution status
// --------------------------------------------------

let status;


// All results are duplicates / no effective changes

if (
  summary.success === 0 &&
  summary.partial === 0 &&
  summary.failed === 0 &&
  summary.duplicate > 0
) {

  status =
    "completed_no_changes";
}


// One or more hard failures and no successful/partial executions

else if (
  summary.failed > 0 &&
  summary.success === 0 &&
  summary.partial === 0
) {

  status =
    "failed";
}


// Partial execution without hard failures

else if (
  summary.partial > 0 &&
  summary.failed === 0
) {

  status =
    "completed_partial";
}


// Mixed failures with successful and/or partial work

else if (
  summary.failed > 0
) {

  status =
    "completed_with_errors";
}


// Normal completion

else {

  status =
    "completed";
}


// --------------------------------------------------
// 5. Build canonical execution bundle
// --------------------------------------------------

return [
  {
    json: {

      response_execution_bundle_version:
        "1.0",

      alert_id:
        alertId,

      status,

      execution_summary:
        summary,

      execution_results:
        results,

      audit: {

        generated_at:
          new Date().toISOString(),

        execution_mode:
          "mock",

        durable_idempotency:
          false
      }
    }
  }
];

// ==================================================
// Canonical Successful Execution Result
//
// Normalizes a response connector result into the
// canonical execution-result contract.
//
// Despite the node name, this normalizer supports:
// - success
// - partial
// - failed
//
// Duplicate results are normalized in the separate
// Canonical Duplicate Execution Result branch.
//
// Security properties:
// - connector output is treated as untrusted input
// - execution identity must be preserved
// - authorization metadata must remain attached
// - retry metadata is preserved
// - no response action is executed here
// ==================================================

const result = $json;


// --------------------------------------------------
// 1. Validate connector result envelope
// --------------------------------------------------

if (
  !result ||
  typeof result !== "object" ||
  Array.isArray(result)
) {
  throw new Error(
    "Canonical Successful Execution Result requires a connector result"
  );
}


if (
  result.response_connector_result_version !== "1.0"
) {
  throw new Error(
    "Canonical Successful Execution Result requires response_connector_result_version '1.0'"
  );
}


// --------------------------------------------------
// 2. Validate identity fields
// --------------------------------------------------

if (
  typeof result.alert_id !== "string" ||
  result.alert_id.trim() === ""
) {
  throw new Error(
    "Canonical Successful Execution Result requires alert_id"
  );
}


if (
  typeof result.execution_id !== "string" ||
  result.execution_id.trim() === ""
) {
  throw new Error(
    "Canonical Successful Execution Result requires execution_id"
  );
}


if (
  typeof result.action_id !== "string" ||
  result.action_id.trim() === ""
) {
  throw new Error(
    "Canonical Successful Execution Result requires action_id"
  );
}


if (
  typeof result.action !== "string" ||
  result.action.trim() === ""
) {
  throw new Error(
    "Canonical Successful Execution Result requires action"
  );
}


if (
  typeof result.connector !== "string" ||
  result.connector.trim() === ""
) {
  throw new Error(
    "Canonical Successful Execution Result requires connector"
  );
}


// --------------------------------------------------
// 3. Validate target
// --------------------------------------------------

if (
  !result.target ||
  typeof result.target !== "object" ||
  Array.isArray(result.target)
) {
  throw new Error(
    "Canonical Successful Execution Result requires target"
  );
}


if (
  typeof result.target.type !== "string" ||
  result.target.type.trim() === ""
) {
  throw new Error(
    "Canonical Successful Execution Result requires target.type"
  );
}


if (
  typeof result.target.value !== "string" ||
  result.target.value.trim() === ""
) {
  throw new Error(
    "Canonical Successful Execution Result requires target.value"
  );
}


// --------------------------------------------------
// 4. Validate status
// --------------------------------------------------

const allowedStatuses = [
  "success",
  "partial",
  "failed"
];


if (
  !allowedStatuses.includes(
    result.status
  )
) {
  throw new Error(
    `Canonical Successful Execution Result received unsupported status '${result.status}'`
  );
}


// --------------------------------------------------
// 5. Validate outcome
// --------------------------------------------------

if (
  !result.outcome ||
  typeof result.outcome !== "object" ||
  Array.isArray(result.outcome)
) {
  throw new Error(
    "Canonical Successful Execution Result requires outcome"
  );
}


if (
  typeof result.outcome.changed !== "boolean"
) {
  throw new Error(
