    "Canonical Successful Execution Result requires retry.retryable boolean"
  );
}


if (
  result.retry.error_type !== null &&
  result.retry.error_type !== undefined &&
  (
    typeof result.retry.error_type !== "string" ||
    result.retry.error_type.trim() === ""
  )
) {
  throw new Error(
    "retry.error_type must be null or a non-empty string"
  );
}


// --------------------------------------------------
// 7. Validate execution metadata
// --------------------------------------------------

if (
  !result.execution_metadata ||
  typeof result.execution_metadata !== "object" ||
  Array.isArray(result.execution_metadata)
) {
  throw new Error(
    "Canonical Successful Execution Result requires execution_metadata"
  );
}


if (
  typeof result.execution_metadata.idempotency_key !== "string" ||
  result.execution_metadata.idempotency_key.trim() === ""
) {
  throw new Error(
    "Canonical Successful Execution Result requires idempotency_key"
  );
}


if (
  result.execution_metadata.idempotency_key !==
  result.execution_id
) {
  throw new Error(
    "idempotency_key must exactly match execution_id"
  );
}


const attempt =
  result.execution_metadata.attempt ?? 1;


const maxAttempts =
  result.execution_metadata.max_attempts ?? 2;


if (
  !Number.isInteger(attempt) ||
  attempt < 1
) {
  throw new Error(
    "execution_metadata.attempt must be an integer >= 1"
  );
}


if (
  !Number.isInteger(maxAttempts) ||
  maxAttempts < 1
) {
  throw new Error(
    "execution_metadata.max_attempts must be an integer >= 1"
  );
}


if (
  attempt > maxAttempts
) {
  throw new Error(
    "execution_metadata.attempt cannot exceed max_attempts"
  );
}


if (
  typeof result.execution_metadata.started_at !== "string" ||
  Number.isNaN(
    Date.parse(
      result.execution_metadata.started_at
    )
  )
) {
  throw new Error(
    "Canonical Successful Execution Result requires valid started_at"
  );
}


if (
  typeof result.execution_metadata.completed_at !== "string" ||
  Number.isNaN(
    Date.parse(
      result.execution_metadata.completed_at
    )
  )
) {
  throw new Error(
    "Canonical Successful Execution Result requires valid completed_at"
  );
}


// --------------------------------------------------
// 8. Validate authorization
// --------------------------------------------------

if (
  !result.authorization ||
  typeof result.authorization !== "object" ||
  Array.isArray(result.authorization)
) {
  throw new Error(
    "Canonical Successful Execution Result requires authorization"
  );
}


if (
  typeof result.authorization.approval_request_id !== "string" ||
  result.authorization.approval_request_id.trim() === ""
) {
  throw new Error(
    "Canonical Successful Execution Result requires authorization.approval_request_id"
  );
}


if (
  typeof result.authorization.approved_by !== "string" ||
  result.authorization.approved_by.trim() === ""
) {
  throw new Error(
    "Canonical Successful Execution Result requires authorization.approved_by"
  );
}


if (
  typeof result.authorization.approved_at !== "string" ||
  Number.isNaN(
    Date.parse(
      result.authorization.approved_at
    )
  )
) {
  throw new Error(
    "Canonical Successful Execution Result requires valid authorization.approved_at"
  );
}


// --------------------------------------------------
// 9. Validate retry semantics
// --------------------------------------------------
//
// Retryable=true is only meaningful for failed
// connector executions.
//
// Success and partial results must not be marked as
// retryable in this Phase 10 policy.
// --------------------------------------------------

if (
  result.status !== "failed" &&
  result.retry.retryable === true
) {
  throw new Error(
    `status '${result.status}' cannot be retryable`
  );
}


if (
  result.status === "success" &&
  result.retry.error_type !== null
) {
  throw new Error(
    "successful execution must not contain retry.error_type"
  );
}


// --------------------------------------------------
// 10. Derive canonical execution semantics
// --------------------------------------------------

const successful =
  result.status === "success";

const partial =
  result.status === "partial";

const failed =
  result.status === "failed";


// --------------------------------------------------
// 11. Derive retry eligibility
// --------------------------------------------------

const retryEligible =
  failed &&
  result.retry.retryable === true &&
  attempt < maxAttempts;


// --------------------------------------------------
// 12. Build canonical execution result
// --------------------------------------------------

return [
  {
    json: {

      response_execution_result_version:
        "1.0",

      alert_id:
        result.alert_id,

      execution_id:
        result.execution_id,

      action_id:
        result.action_id,

      action:
        result.action,

      target: {
        type:
          result.target.type,

        value:
          result.target.value
      },

      connector:
        result.connector,

      status:
        result.status,

      successful,

      partial,

      failed,

      duplicate:
        false,

      changed:
        result.outcome.changed,

      message:
        result.outcome.message,

      retry: {

        retryable:
          result.retry.retryable,

        error_type:
          result.retry.error_type ?? null,

        retry_eligible:
          retryEligible
      },

      execution_metadata: {

        mode:
          result.execution_metadata.mode || "unknown",

        environment:
          result.execution_metadata.environment || "unknown",

        idempotency_key:
          result.execution_metadata.idempotency_key,

        attempt,

        max_attempts:
          maxAttempts,

        started_at:
          result.execution_metadata.started_at,

        completed_at:
          result.execution_metadata.completed_at
      },

      authorization: {

        approval_request_id:
          result.authorization.approval_request_id,

        approved_by:
          result.authorization.approved_by,

        approved_at:
          result.authorization.approved_at
      }
    }
  }
];

