if (
  result.response_execution_result_version !== "1.0"
) {
  throw new Error(
    "Retry Execution Request Builder requires response_execution_result_version '1.0'"
  );
}


if (
  result.status !== "failed" ||
  result.failed !== true
) {
  throw new Error(
    "Retry Execution Request Builder only accepts failed executions"
  );
}


