  );
}


if (
  !Number.isInteger(maxAttempts) ||
  maxAttempts < 1
) {
  throw new Error(
    "Retry Execution Request Builder requires valid max_attempts"
  );
}


if (
  attempt >= maxAttempts
) {
  throw new Error(
    "Retry Execution Request Builder cannot exceed max_attempts"
  );
}


const nextAttempt =
  attempt + 1;


// --------------------------------------------------
// 3. Validate authorization
// --------------------------------------------------

if (
  !result.authorization ||
  typeof result.authorization !== "object" ||
  Array.isArray(result.authorization)
) {
  throw new Error(
