      evidence_sources:
        [],

      authorization:
        result.authorization,

      execution_context: {

        mode:
          result.execution_metadata.mode,

        environment:
          result.execution_metadata.environment,

        idempotency_key:
          result.execution_metadata.idempotency_key,

        attempt:
          nextAttempt,

