  }


  if (
    result.status === "success"
  ) {
    calculated.success++;
  }


  if (
    result.status === "partial"
  ) {
    calculated.partial++;
  }


  if (
    result.status === "failed"
  ) {
    calculated.failed++;
  }


  if (
    result.status === "duplicate"
  ) {
    calculated.duplicate++;
  }


  if (
    result.changed === true
  ) {
    calculated.changed++;
  } else {
    calculated.unchanged++;
  }
}


for (
  const field
  of Object.keys(calculated)
) {

  if (
    summary[field] !==
    calculated[field]
  ) {
    throw new Error(
      `execution_summary.${field} does not match execution results`
    );
  }
}


// --------------------------------------------------
// 3. Build action audit records
// --------------------------------------------------

const actionAudit =
  bundle.execution_results.map(
    result => {

      const retry =
        result.retry &&
        typeof result.retry === "object"
          ? result.retry
          : {
              retryable:
                false,

              error_type:
                null,

              retry_eligible:
                false
            };


      return {

        execution_id:
          result.execution_id,

        action_id:
          result.action_id,

        action:
          result.action,

        target:
          result.target,

        connector:
          result.connector,

        status:
          result.status,

        changed:
          result.changed,

        message:
          result.message,

        attempt:
          result.execution_metadata?.attempt ?? 1,

        max_attempts:
          result.execution_metadata?.max_attempts ?? 1,

        retry:
          {
            retryable:
              retry.retryable === true,

            retry_eligible:
              retry.retry_eligible === true,

            error_type:
              retry.error_type ?? null
          },

        idempotency:
          {
            key:
              result.execution_metadata?.idempotency_key ?? null,

            duplicate:
              result.duplicate === true
          },

        authorization:
          {
            approval_request_id:
              result.authorization?.approval_request_id ?? null,

            approved_by:
              result.authorization?.approved_by ?? null,

            approved_at:
              result.authorization?.approved_at ?? null
          },

        timing:
          {
            started_at:
              result.execution_metadata?.started_at ?? null,

            completed_at:
              result.execution_metadata?.completed_at ?? null
          }
      };
    }
  );


// --------------------------------------------------
// 4. Collect authorization references
// --------------------------------------------------

const approvalRequestIds =
  [
    ...new Set(
      actionAudit
        .map(
          record =>
            record.authorization.approval_request_id
        )
        .filter(Boolean)
    )
  ];


const approvers =
  [
    ...new Set(
      actionAudit
        .map(
          record =>
            record.authorization.approved_by
        )
        .filter(Boolean)
    )
  ];


// --------------------------------------------------
// 5. Derive retry metrics
// --------------------------------------------------

const retryMetrics = {

  actions_reaching_retry_attempt:
    actionAudit.filter(
      record =>
        record.attempt > 1
    ).length,

  retryable_terminal_failures:
    actionAudit.filter(
      record =>
        record.status === "failed" &&
        record.retry.retryable === true
    ).length,

  non_retryable_failures:
    actionAudit.filter(
      record =>
        record.status === "failed" &&
        record.retry.retryable === false
    ).length
};


// --------------------------------------------------
// 6. Build final audit record
// --------------------------------------------------

return [
  {
    json: {

      response_execution_audit_version:
        "1.0",

      alert_id:
        bundle.alert_id,

      execution_status:
        bundle.status,

      execution_summary:
        bundle.execution_summary,

      retry_summary:
        retryMetrics,

      authorization_summary:
        {
          approval_request_ids:
            approvalRequestIds,

          approvers:
            approvers,

          authorization_present:
            actionAudit.every(
              record =>
                Boolean(
                  record.authorization.approval_request_id
                ) &&
                Boolean(
                  record.authorization.approved_by
                ) &&
                Boolean(
                  record.authorization.approved_at
                )
            )
        },

      security_properties:
        {
          execution_mode:
            "mock",

          real_external_actions:
            false,

          durable_idempotency:
            false,

          human_approval_preserved:
            true,

          max_attempts_enforced:
            true
        },

      action_audit:
        actionAudit,

      generated_at:
        new Date().toISOString()
    }
  }
];
